INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021175', 'AN1924', '宮村伊澄', '宮村は、そのひそやかな性格のせいで、よくオタクと間違えられる。彼が長い髪や服で身を隠しているのは、ピアスや数え切れないほどのタトゥーを隠すためなのだ。これは、堀と石川だけが知っている秘密だ。  泉はとても思いやりのある少年だ。見た目は弱そうだが、実はとても強い。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b66173-g8eU1LGWPB8O.png', '4月17日', NULL, '内山昂輝', 169, 66173, 'MAIN', 15841) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021176', 'AN1924', '堀京子', '堀京子は、宮村伊澄と並んで『ホリミヤ』の主要な主人公の一人です。彼女は片桐高校3年1組の生徒です。京子は概してとても元気で人気者であり、いつも周囲を明るい雰囲気に包んでいます。 彼女は生活のあらゆる面で努力家であり、宮村伊澄によると、テストの成績はすべて90％以上をキープしているという。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b66171-o2vk3689wWFK.png', '3月25日', NULL, '戸松遥', 163, 66171, 'MAIN', 12408) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021177', 'AN1924', '柳明音', '彼は片桐高校の3年生で、堀と宮村の常連の友人グループの一員である。3年6組に在籍している。視力が非常に悪く、眼鏡をかけないとまともに物が見えない。', 18, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b72453-f9gRbQBUjKo6.png', '12月28日', NULL, '福山潤', 168, 72453, 'SUPPORTING', 1175) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021178', 'AN1924', '西貴子', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b203892-t0pUbFpAjheN.png', NULL, NULL, '高田憂希', NULL, 203892, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021179', 'AN1924', '奥山有菜', 'ユンナはソタの同級生だ。彼女はソタをいじめているが、実は彼のことがとても好きだ。堀京子は彼女の憧れの存在だ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b66971-yfKmxIsWKWyR.jpg', NULL, NULL, '古賀葵', NULL, 66971, 'SUPPORTING', 65) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021180', 'AN1924', '井浦基子', '彼女は井浦秀の妹である。自らを「無口で陰気なタイプ」と評する元子は、秀とは正反対の性格だ。一人でいることが多く、友達を作るのが苦手だ。 しかし、修とは異なり、この性格は学校生活にも表れており、他人に対しては控えめなものの、兄に対してははるかに強引で暴力的になる。また、彼女はかなり頭が良いが、その能力を十分に活かす自信に欠けている。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b72467-PpdDmPQFbaMC.png', '5月14日', NULL, '金元寿子', 150, 72467, 'SUPPORTING', 146) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021181', 'AN1924', '一条千佳', 'チカは八坂高校の3年生です。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b72463-TKhUXOPgcmv3.jpg', '9月26日', NULL, '千本木彩花', 154, 72463, 'SUPPORTING', 33) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021182', 'AN1924', '矢代加世', '石川家の家政係。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b215830-UqoX5c4HSqw4.png', NULL, NULL, '柚木涼香', 176, 215830, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021183', 'AN1924', '吉川由紀', '堀京子の親友で、彼女と同じ高校に通っている。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b66963-JBKCtpgwdgkG.png', '7月22日', NULL, '小坂井祐莉絵', NULL, 66963, 'SUPPORTING', 2611) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021184', 'AN1924', '谷原マキオ', '彼はカシ高校に通う高校3年生だ。宮村や新藤と同じ中学校に通っていた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b72465-IVbmlZUoptvt.jpg', '4月16日', NULL, '千葉翔也', 168, 72465, 'SUPPORTING', 61) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021185', 'AN1924', '安田真', '職業：英語教師　所属：片桐高校生徒会（役員）　『ホリミヤ』の脇役の一人である。安田は女子高生が大好きで、それを隠そうともしていない。 しかし、実際に女子生徒に触れることは決してなく、ただ彼女たちには過度に親しげに振る舞い、男子生徒たちには過度に冷たく接するだけだ。彼はよく、彼女がいる男子生徒（主に宮村や仙石）に対し、自分がその女子生徒を独り占めできるようにと、別れを迫ることがある。彼が一緒にいるときはいつでも', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b66975-1ENOxQZ7SJPm.png', NULL, NULL, '津田健次郎', NULL, 66975, 'SUPPORTING', 124) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021186', 'AN1924', '石川透', 'トオルは誰に対しても親しみやすく、穏やかな性格だ。彼は片桐高校に通っている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b66961-VZV5IwKUwYfp.png', '10月1日', NULL, '山下誠一郎', 174, 66961, 'SUPPORTING', 1493) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021187', 'AN1924', '堀百合子', '彼女は京子とソータの母親です。', 36, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b78279-Vyv16wSznsYl.jpg', NULL, NULL, '茅野愛衣', NULL, 78279, 'SUPPORTING', 210) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021188', 'AN1924', '溝内大樹', '彼は堀と宮村の同級生の一人だ。同じ学校に通っており、同じ3年1組に在籍している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b72457-urLH3qxflfRj.png', '8月24日', NULL, '石谷春貴', 176, 72457, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021189', 'AN1924', '仙石翔', '彼は、片桐高校の生徒会会長であり、3年3組に在籍するカリスマ的な人物で、堀京子の幼なじみであり、綾崎レミの彼氏でもある。  仙石は、少し内気で恥ずかしがり屋な少年であり、些細なことで怯えてしまうほど臆病で、特にホラーや虫に関するものには恐怖で縮こまってしまう。仙石は非常に頭が良くて真面目な性格で、普段は学内で1位（体育の成績は2位）を維持している。 読書が好きで、信じられないほどの……', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b72447-SH9Hth8ZGJam.png', '5月9日', NULL, '岡本信彦', 170, 72447, 'SUPPORTING', 756) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021190', 'AN1924', '進藤晃一', '彼はこのシリーズの脇役だ。彼は泉や真生と同じ中学校に通っていた。', 18, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b72461-4zzQ6cShYe8l.png', '4月2日', NULL, '八代拓', 173, 72461, 'SUPPORTING', 388) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021191', 'AN1924', '吉川美紀', 'ユキの姉。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b212578-b5u2nVSdkP0f.png', NULL, NULL, '種﨑敦美', NULL, 212578, 'SUPPORTING', 30) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021192', 'AN1924', '河野桜', '彼女は学生自治会の副会長です。彼女はとても有能で、よくサポート業務を行っています。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b72449-wTynovkFnQpC.png', '1月20日', NULL, '近藤玲奈', 163, 72449, 'SUPPORTING', 942) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021193', 'AN1924', '沢田ほのか', '沢田は堀京子に対して非常にべったりしている。堀への執着から、堀が宮村伊澄と一緒にいるとよく怒り出し、彼を遠ざけようとする。彼女は宮村を恋のライバルであると同時に、兄弟のような存在とも見なしている。 彼女は数年前に亡くなった兄と非常に仲が良かった。また、軽度の男性恐怖症の傾向があり、男性に近づかれると、しばしば固まってしまったり、逃げ出したり、隠れたりしてしまう。しかし、宮村と知り合ってからは、代わりに彼の後ろに隠れるようになった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b72459-NbyXnBAjLxKT.png', '12月31日', NULL, '麻倉もも', 150, 72459, 'SUPPORTING', 762) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021194', 'AN1924', '寺島玲子', '彼女は片桐高校の化学教師であり、3年1組の担任です。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b66973-cRamsBQtjWmG.png', NULL, NULL, '佐藤はな', NULL, 66973, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021195', 'AN1924', '綾崎レミ', '生徒会のメンバーであり、片桐高校に通う仙石翔の彼女として知られている。同校の3年5組に在籍している。生徒会ではどちらかといえばマスコット的な存在で、仕事はほとんど、あるいは全くしていない様子が描かれている。   レミは、概してかなり子供っぽく未熟な少女として描かれており、非常に率直な性格で、感情を隠さず表に出すことが多い。また、他人の助けに頼りがちなところもある。頭もあまり良くなく、よく宮村と比べられる。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b66965-Kfqui6IitXaL.png', '6月6日', NULL, '市道真央', 158, 66965, 'SUPPORTING', 1703) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021196', 'AN1924', '堀創太', '京子の弟。両親の仕事の都合で、生まれてからずっと京子に世話になってきたため、彼は京子を母親のような存在として見ている。  物語の冒頭、彼は路上で転んでしまったところを和泉に助けられ、堀家へ連れ戻される。それ以来、彼は和泉に対して非常に親しみを示しており、血のつながりはないものの「兄弟」と呼ぶほどである。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b66969-w9HNa7igeTeF.png', '10月18日', NULL, '寺崎裕香', NULL, 66969, 'SUPPORTING', 573) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021197', 'AN1924', '宮村伊織', '職業：宮村家の店のオーナー兼経営者。宮村直純の妻であり、宮村伊澄の母である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b207325-wjqrISdImoOl.png', NULL, NULL, '大原さやか', NULL, 207325, 'SUPPORTING', 31) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021198', 'AN1924', '井浦秀', '彼は宮村伊澄や、scholのほぼ全員と親しい間柄だ。独自の考え方を持ち、いつも活気にあふれている。別のクラスの同僚である。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b66967-driczOA04cxe.png', '2月7日', NULL, '山下大輝', 172, 66967, 'SUPPORTING', 995) ON CONFLICT DO NOTHING;
