INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021423', 'AN1936', 'ドーム', '種：クジャク　ドームはチェリートン・アカデミーに通っており、レゴシと共に演劇部のメンバーである。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b160358-M7Issc6OQeBp.jpg', '11月5日', NULL, '室元気', NULL, 160358, 'SUPPORTING', 29) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021424', 'AN1936', 'ピナ', 'ピナは『ビーストスターズ』に繰り返し登場するキャラクターである。チェリートン・アカデミーの演劇部で、1年生であり新入部員として登場した。', 16, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b132947-RYIRivJeF6vR.png', '12月27日', 'B', '梶裕貴', 174, 132947, 'SUPPORTING', 418) ON CONFLICT DO NOTHING;
