INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021433', 'AN1936', 'ジャック', '犬種：ラブラドール・レトリバー　レゴシのルームメイトの一人であり、長年にわたり親友でもあるジャックは、ごく普通の男だ。彼は、特にハルに関わるレゴシの行動にしばしば戸惑うこともあるが、親友のためならいつでも力になってくれる。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b132982-hy5W6uQCvVYW.png', '12月22日', NULL, '榎木淳弥', NULL, 132982, 'SUPPORTING', 659) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021434', 'AN1936', 'フリー', '「シシグミ」の現役メンバーであるインディアン・ライオン。', 30, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b194483-GslsNZuC3eZN.png', '9月13日', 'A', '木村昴', NULL, 194483, 'SUPPORTING', 25) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021435', 'AN1936', 'カール', 'テムの友人であり、エルスの元カレ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b204636-dE4Zmw1t71U2.png', NULL, NULL, '安田陸矢', NULL, 204636, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021436', 'AN1936', 'シイラ', '彼女は『ビーストスターズ』の脇役です。チェリートン・アカデミーの演劇部で、振付主任を務めています。漫画版ではシェリアはチーターですが、アニメ版ではヒョウとなっています。', 18, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b160350-7dtrCieQXsyt.png', '6月21日', NULL, '原優子', 160, 160350, 'SUPPORTING', 28) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021437', 'AN1936', 'サヌ', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b160349-CRxtr3dDKv4U.png', NULL, NULL, '落合福嗣', NULL, 160349, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021438', 'AN1936', 'ボス', 'ほっそりとした体つきで、体がとても小さいフェネックキツネ。レゴシと同じ「犬族701」の一員だ。体が小さいため、寮の同室であるコロに背中に乗せてもらっている姿をよく見かける。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b160353-ce7ze5gYPlOu.png', '2月14日', 'A', '下妻由幸', 40, 160353, 'SUPPORTING', 23) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021439', 'AN1936', 'ロクメ', 'ロクメは『ビーストスターズ』に登場する脇役の一人です。彼女はチェリートン・アカデミーの唯一の警備員です。ロクメはとても臆病な性格で、いつも人目につかない場所に隠れているため、普段は誰ともほとんど交流しません。 また、ロクメは（特にレゴシの行動に対して）すぐに興奮してしまう傾向がある。彼女自身、手足がないという「恥」を生まれつき背負っており、隠れてこそそれを耐え忍ぶことができるため、レゴシを羨ましく思っているとも語っている。（出典：Beastars Fandom Wiki）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b204637-Bw76iZjWSjJC.png', NULL, NULL, 'くじら', NULL, 204637, 'SUPPORTING', 36) ON CONFLICT DO NOTHING;
