INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021690', 'AN1946', '末森荊', '彼女は清英高校の2年生で、女子バレーボール部の部員です。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b314046-W5LSNCpTyFhu.jpg', NULL, NULL, '鈴代紗弓', NULL, 314046, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
