INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021982', 'AN1960', 'チョンギーレ', '「遅延の魔女」の配下。チョンギーレは「ヤラネーダ」を用いて戦い、モチベーションの力を吸収する。本職はシェフである。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b210109-ZzLmjIbD3Oyj.png', NULL, NULL, '白熊寛嗣', NULL, 210109, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
