INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH021994', 'AN1960', '月影ゆり', 'ユリはモモカの同級生で、同じく明道学園高校部の2年生だ。モモカが仕事の都合で授業に出席できないときは、ユリが授業のノートを提供している。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b32195-GhMucyqfH55R.jpg', NULL, NULL, '久川綾', NULL, 32195, 'SUPPORTING', 167) ON CONFLICT DO NOTHING;
