INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022284', 'AN1976', '垣谷ユイ', '垣谷ユウゴの孫娘であり、トアックのメンバー。AIとの共存を目指す穏健派グループのリーダーである。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b231664-NA1x71XvXXf7.jpg', NULL, NULL, '朝井彩加', NULL, 231664, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022285', 'AN1976', '松本オサム', '「マツモト」を100年前に送り込み、歴史を変えるAI研究者。彼はマツモト用のAIを開発した人物であり、この分野における世界屈指の専門家の一人である。（出典：公式サイト、翻訳）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b216424-WPce9wRsYH87.jpg', NULL, NULL, '子安武人', NULL, 216424, 'SUPPORTING', 79) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022286', 'AN1976', '霧島ユズカ', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b217730-QISrV0LvgaQm.jpg', NULL, NULL, '小原好美', NULL, 217730, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022287', 'AN1976', '相川ヨウイチ', 'AIに人権を認める「AI命名法」の成立に向けて取り組んでいる州議会議員。人当たりは良いが、特筆すべき実績はない。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b216425-x180DPnFLTci.jpg', NULL, NULL, '加藤将之 ', NULL, 216425, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022288', 'AN1976', 'エリザベス', 'エステラの双子の妹。エステラと同時に生み出されたが、実験の末に廃棄された。その後、反AI組織「トアク」に保護され、そこで戦闘能力を身につけた。エステラに比べ、性格は非常に攻撃的である。（出典：公式サイト、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b218484-RimHPK0rmery.jpg', NULL, NULL, '内山夕実', NULL, 218484, 'SUPPORTING', 92) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022289', 'AN1977', '草摩慊人', 'アキトは相馬一族の当主だが、非常に虚弱である。頻繁に高熱を出し、外の世界に住むユキやシグレといった十二支のメンバーに挨拶をする時を除いて、本邸の外に出ることはめったにない。 アキトには紛れもない冷酷な一面があり、相馬家の多くの者に肉体的・精神的な傷を負わせてきたが、相馬一族におけるアキトの支配は絶対的であり、誰も彼に逆らうことはできない。アキトの呪いの一因として、彼が30歳までしか生きられないという説もある。ある時点で', 19, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b374-8BT4gMd8xyl5.png', NULL, NULL, '坂本真綾', NULL, 374, 'MAIN', 766) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022290', 'AN1977', '草摩紅葉', '干支：兎　明るく幸せそうに見える10代の少年だが、その陽気な態度の裏には、悲しい家庭環境が隠されている。 彼の絶え間ない愚痴や泣き言は、しばしば京を苛立たせる。彼は見た目より年上で、透を驚かせたことに、由紀よりわずか1歳年下であり、京とは初春と同じ年齢である。 モミジは十二支の「兎」であり、相馬家の比較的裕福な一族の息子である。父親は日本人で、母親はドイツ人だ。トーリは知らず知らずのうちに、モミジの父親の車を掃除してしまう。', 15, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b367-Jc6wMVpL76Ib.png', NULL, NULL, '潘めぐみ', NULL, 367, 'SUPPORTING', 2654) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022291', 'AN1977', '藤堂公', '彼女は生徒会に所属していて、「悪魔のような女性」として知られている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b6572-QnQqn3nrVMV9.png', NULL, NULL, '大久保瑠美', NULL, 6572, 'SUPPORTING', 53) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022292', 'AN1977', '夾の母', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b235701-sVjvY4m9v2bo.png', NULL, NULL, '湯屋敦子', NULL, 235701, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022293', 'AN1977', '草摩潑春', '学年／学校：海原高校1年生　干支：丑　丑年生まれのハルは、丑の性格に由来する陰と陽の両面を併せ持つような性格だ。 普段は穏やかで物静か、何と言っても好青年だが、煽られると「暴走」状態になり、その時は神経質で意地悪になり、性欲がやや高ぶってしまう。ホワイト・ハルは「ブラック」に変身している間も意識はあるが、それを止めることはできない。 彼はただ謝るか、あるいは気にも留めないかのどちらかだ。さらに、ハルのセ', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b369-NDFi2A2BzqO6.png', NULL, 'O', '古川慎', NULL, 369, 'SUPPORTING', 4113) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022294', 'AN1977', '桜木直人', 'ユキをライバルと見なし、モトコに想いを寄せている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b6573-SDj1s63gWr9I.jpg', NULL, NULL, '市川蒼', NULL, 6573, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022295', 'AN1977', '倉前美音', '倉前美音は、草摩綾目の服飾店でデザイナー兼裁縫師として働き、店の上にあるアパートで彼と同居している。情熱的で陽気な性格で、綾目のためなら何でもする覚悟がある。綾目が熱意のあまり見落としがちな細かいこと、例えば由紀のクラスへの訪問許可を得るといったことも、彼女がしっかりと引き受けてくれる。 高屋夏樹によれば、綾目のペースについていける彼女は「素晴らしい人」だという。彼女は、自分の作った服で女の子たちを着飾らせることに特に情熱を注いでいる様子が描かれている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b13956-qRFyJI2pS9GS.png', NULL, NULL, '井口裕香', NULL, 13956, 'SUPPORTING', 48) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022296', 'AN1977', '草摩五月', '草摩さつきは、ヒロと草摩日向の母親である。  （出典：フルーツバスケット・ファンダム）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b243718-qI4POBMuf17s.png', NULL, NULL, '高橋美佳子', NULL, 243718, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022297', 'AN1977', '白木繭子', 'Mayuko Shiraki (白木 繭子, Shiraki Mayuko) is Tohru, Kyo, Yuki, Saki, and Arisa''s homeroom teacher; what subject she teaches is never given, though in an author''s note, Natsuki Takaya said she thinks Shiraki fits the image of a literature teacher. Shiraki is depicted as generally good-humored but sometimes aggressive—when Kyo attempts to leave class on Valentine''s Day, she stops him at the door with a folder in his face and threatens to dye his hair black instead of orange, and once breaks up a figh', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b27831-kQaWdyJjdO7H.png', NULL, NULL, '生天目仁美', NULL, 27831, 'SUPPORTING', 102) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022298', 'AN1977', '草摩綾女', '干支：蛇　干支の「蛇」であり、ユキの兄であるアヤメは、活発でおしゃべりで、ユキやキョウを怒らせるのが得意だ。彼は婦人服の製造・販売業を営んでおり、その服は男性も着ているらしい。彼自身もよく婦人服を着ている。 彼は自分の名前を店名にし、後にアヤメの恋人であり、店の仕立て屋であることが明らかになるミネと共に店を経営している。アヤメはドレスのデザインを担当しており、その中にはエロティックなものもいくつか、あるいはすべて含まれているかもしれない。虚栄心が強く、やや自己中心的な', 27, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b370-cdEW33vBsXBL.png', NULL, NULL, '櫻井孝宏', NULL, 370, 'SUPPORTING', 1570) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022299', 'AN1977', '真鍋翔', '漫画の第49話（第9巻）で初登場した真鍋は、当初は少々怠け者だが、社交的で陽気な青年として描かれており、それ以来その性格は変わっていない。 海原高校の生徒会副会長を務めるカケルは、「学校防衛隊の副隊長」であり、自身が「スーパー戦隊」のような仕事だと考えているその役割に情熱を注いでいる。彼はよく、自分は「ブラック」 （ゴレンジャーの「黒」のように）とよく口にする一方、ユキは「赤」だ（', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b4957-fNOpYP6mIeWu.png', NULL, NULL, '江口拓也', NULL, 4957, 'SUPPORTING', 457) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022300', 'AN1977', '本田今日子', '透の母親：京子は若い頃、トラブルを起こしたり学校をサボったりしており、暴力団同士の抗争をきっかけに両親から勘当された。父親は「この世に京子など必要ない」と考えており、母親は家族の体面ばかりを気にかけていたため、彼女は家族を憎んでいた。 また、彼女は女子だけの自殺ギャングのリーダーでもあった。そこでは「赤い蝶」と呼ばれていたが、この名前は、夜間にバイクを走らせると、テールライトが鮮やかな赤い蝶のように舞うという伝説に由来している。', 33, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b9754-PGxNeo2JwGx9.jpg', NULL, NULL, '沢城みゆき', NULL, 9754, 'SUPPORTING', 753) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022301', 'AN1977', '皆川素子', 'モトコはとても執着心が強く、ロマンチックで、意志が固い。欲しいもの（あるいは人）を手に入れるためなら、どんな手段も厭わないが、必ずしも成功するとは限らない。 モトコは、片思いの相手である草摩ユキについて、よく愛の詩を綴っている。彼女は常にユキのことを考え、その話題で持ちきりだ。また、海原高校の「プリンス・ユキファンクラブ」の会長も務めている。彼女は主に遠くからユキを慕っており、実際に彼と話すことはめったにない。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b3874-N631hTrXB2Kg.jpg', NULL, NULL, '市道真央', NULL, 3874, 'SUPPORTING', 40) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022302', 'AN1977', '草摩楝', '草摩楝はアキトの母親である。レンはもともと草摩家の使用人だったが、当時の草摩家当主であるアキラの深い孤独に唯一気づき、単なる当主としてではなく、親切に接したことで、彼の心を掴んだのである。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b9755-9sOqyxC89M7D.png', NULL, NULL, '折笠愛', NULL, 9755, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022303', 'AN1977', '草摩紅野', '干支：酉　クレノは物静かで従順な男だ。', 26, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b4644-s7NSkE6KYFhe.jpg', NULL, NULL, '梅原裕一郎', NULL, 4644, 'SUPPORTING', 385) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022304', 'AN1977', '倉伎真知', '倉伎真知は、漫画『フルーツバスケット』に登場する架空の人物で、海原高校の生徒会会計を務めている。真知は物静かで内気な性格で、繊細でやや孤立しているように見える。彼女は漫画『フルーツバスケット』およびドラマCDに登場し、声優は海田由紀が担当している。    マチは真鍋翔の異母妹である。真鍋は彼女を非常に大切にしており、兄弟としての優越感というよりは、兄としての愛情から、よく彼女に指図をしている姿が見られる。    マチはとても物静かな', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b6571-H6JruBvnORjl.jpg', NULL, NULL, '加隈亜衣', NULL, 6571, 'SUPPORTING', 620) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022305', 'AN1977', '神様', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b231889-SHd6QPgXna62.png', NULL, NULL, '神谷浩史', NULL, 231889, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022306', 'AN1977', '草摩晶', '草摩晶は、かつて草摩家の当主だった。彼は草摩慊人の父であり、草摩楝の夫でもある。アキラは、アキトに「あなたは選ばれた子、愛されるために生まれた子だ」と告げた人物だった。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b212557-443D3jIpFm96.png', NULL, NULL, '石田彰', NULL, 212557, 'SUPPORTING', 18) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022307', 'AN1977', '草摩利津', '干支：申　彼が物心ついた頃から、自分のしたことは何でも両親が謝らなければならなかったため、彼は自分に自信が持てない。毎日、呼吸をするたびに、世界から空気を奪っているような気がしている。  女の子のような格好をしていると、いつも気持ちが楽になることに気づいたが、それは両親に謝る理由をさらに増やすだけだった。彼は女の子にそっくりなので、トオルも初めて彼を見たときはそう思っていたが、彼がうっかり変身してしまうまでは。どういうわけか、トオルは彼を説得して……', 21, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b373-2hzWde5fNiwk.png', NULL, NULL, '河西健吾', NULL, 373, 'SUPPORTING', 197) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022308', 'AN1977', '魚谷ありさ', 'アリサは元ギャング（*ヤンキー*：アメリカの「ギャング」イメージを日本風にアレンジしたもの）で、トオルが「レディース」というギャングから抜け出したいと願っていた際、トオルの母親が彼女を助けて以来、トオルの最も親しい友人の一人となっている。  アリサはタフで、奔放、時には暴力的だが、友人に関することになるとすぐに涙を流してしまう。彼女はロングスカートをはき、鉛パイプを持ち歩き、よく男のような話し方をする（日本語では、言葉の選び方によって話し手が男性か女性かと判断されることがある）。アリサは', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b375-RYqdBrPJL06c.jpg', NULL, NULL, '種﨑敦美', NULL, 375, 'SUPPORTING', 1246) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022309', 'AN1977', '草摩楽羅', '干支：猪　彼女は幼い頃から京に想いを寄せていたが、京が彼女の友人である本田透に想いを寄せていることは知らない。 幼い頃、猫の呪いを背負って一人ぼっちだった彼を「気の毒に」思った彼女は、彼と遊んだり世話をしたりしていた。 やがて、その気持ちは彼に対する、ほとんど執着に近い愛へと発展していった。彼女は、彼と結婚すると確信している。その主な理由は、彼を脅してプロポーズさせたからである（漫画では7歳の時にナイフを突きつけて、あるいは…）。', 19, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b366-5iIIhczrc3Qr.jpg', '7月6日', 'B', '釘宮理恵', NULL, 366, 'SUPPORTING', 315) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022310', 'AN1977', '草摩依鈴', '干支：馬　彼女は意志が強く、頑固で、独立心旺盛な女性であり、一族の他のメンバーがアキトに従う姿を嫌悪している。背が高く、当初は腰までの長さの黒髪をしている。 彼女は孤立しがちだが、時折ヒロと一緒にいる姿が見られる。ヒロは、初春、カグラ、そしてカグラの母親と共に、凛が病院に入院していた間、彼女を訪ねてきた唯一の人々だった。 リンは初春を愛しているが、彼を解放する方法が見つかるまで、彼を守るために別れを告げる。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b3892-Cv49n98SjFIE.png', NULL, 'B', '豊崎愛生', NULL, 3892, 'SUPPORTING', 1870) ON CONFLICT DO NOTHING;
