INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022316', 'AN1978', '白川美保', '職業：看護師　白川は剛力の診療所で看護師として働いている。穏やかで大人びた女性だが、時折いたずらっぽい一面を見せることもある。趣味でカポエイラを習っている。', 28, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b204523-ayTzvGGt1AiT.jpg', NULL, NULL, '飯田里穂', NULL, 204523, 'SUPPORTING', 195) ON CONFLICT DO NOTHING;
