INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022382', 'AN1981', 'リリス', '彼女はキサラギの主任研究員です。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b215443-PnSdh2vQcy8Z.png', NULL, NULL, '石原夏織', NULL, 215443, 'SUPPORTING', 44) ON CONFLICT DO NOTHING;
