INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022387', 'AN1982', 'フルカス', 'フルカスはバビルスの教師です。彼女は「魔法の知識」を教えています。', 65, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b162694-GxQuv3bzVAUV.png', '11月5日', NULL, NULL, NULL, 162694, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
