INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022391', 'AN1982', 'シーダ', 'イルマが遊園地で迷子になったとき、シーダが彼を助けた。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b156469-UNQOYMHFkkwT.png', NULL, NULL, '澁谷梓希', NULL, 156469, 'SUPPORTING', 68) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022392', 'AN1982', 'マルバス・マーチ', 'マルバスはバビルスの教師である。彼は「拷問術」を教えている。彼はマルの弟である。', 28, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b229262-4i11P8eAlHdq.png', '3月9日', NULL, '中村大志', NULL, 229262, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
