INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022401', 'AN1982', 'アザゼル・アンリ', '家族：メリゼ（妻）、アザゼル・アメリ（娘）　アンリは「十三の王冠」の一員であり、悪魔国境管理局の長でもある。アメリの父親である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155682-fZSdpiVPBns0.png', '6月1日', NULL, '遊佐浩二', 195, 155682, 'SUPPORTING', 38) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022402', 'AN1982', 'ウァラク・キー坊', 'ウァラク・キー坊は、クララの末弟です。彼はヴァラック家の三男であり、4人目の子供です。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b155693-g6KkH6pjKSEp.jpg', NULL, NULL, '朝井彩加', NULL, 155693, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
