INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022414', 'AN1982', 'バラム・シチロウ', 'バビルス校の神話動物学の教師。かつてカレゴと同じクラスだったため、二人は親しい友人同士である。チェス（8）ランクの持ち主だ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b151769-xLpsBpGJS1RT.png', '6月7日', NULL, '小西克幸', NULL, 151769, 'SUPPORTING', 287) ON CONFLICT DO NOTHING;
