INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022820', 'AN2001', 'バーニー', 'レティと同様、かつてディアリアに新しい住処について助言を求め、彼の最初のドラゴン旅の仲間となった、気難しい黒竜。彼は、破壊の伝説的な前兆とされる「強大な黒竜」と呼ばれることを、大げさなほど好んでいる。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b238022-HPKwwIyBWBKA.png', NULL, NULL, '津田健次郎', NULL, 238022, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
