INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022925', 'AN2007', 'セスタス', 'スレーブボクサー。ザファールの弟子。闘技場を通じて自由を手に入れることを目指している。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b181245-wlLLOHRYXHs1.jpg', NULL, NULL, '峯田大夢', NULL, 181245, 'MAIN', 19) ON CONFLICT DO NOTHING;
