INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022927', 'AN2007', 'ザファル', 'ケストスの達人。現在、彼が自らの拳の技を受け継ぎ、闘技場で生き残れるよう、かつての技を伝授している。デミトリウスとは昔からの因縁があり、そのせいで現在は身体が不自由になっている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b181249-ePla0JOeCzQu.png', NULL, NULL, '小山力也', NULL, 181249, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
