INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023216', 'AN2027', '蛇賀眩衣', 'イケテルの姉。バイオリンの先生。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b241685-Ridla2A2VJTc.jpg', NULL, NULL, '日笠陽子', NULL, 241685, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023217', 'AN2028', 'ジャヒー', 'ジャヒーはもともとダークレルムの副司令官でした。しかし、マナクリスタルが破壊された後、彼女は小さくて愛らしい少女になってしまいました！現在はウェイトレスのアルバイトをしています。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b124618-wsHo2rR91A9V.png', NULL, NULL, '大空直美', NULL, 124618, 'MAIN', 1334) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023218', 'AN2028', '涼', 'ジャヒーが住んでいるマンションの管理人。彼女の姉は、ジャヒーが働いているレストランのオーナーである。彼女は家賃を回収するためなら暴力も厭わず、姉とは異なり、いつでもジャヒーを路頭に放り出す覚悟がある。 しかし、大家は姉を恐れており、その弱みをジャヒーは時折利用している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b133103-RvqNYl4F2akN.jpg', NULL, NULL, '日笠陽子', NULL, 133103, 'SUPPORTING', 138) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023219', 'AN2028', '魔王', '闇界の支配者であり、ジャヒーにとって唯一の上司であった人物。マナクリスタルの破壊に伴い消滅したが、後に神宮京子の手によって復活した。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b157951-8QZvFaVcHMHp.jpg', NULL, NULL, '岡咲美保', NULL, 157951, 'SUPPORTING', 95) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023220', 'AN2028', 'ちさ', 'ジャヒーが働いているレストランのオーナーです。彼女の姉は、ジャヒーが住んでいるアパートの大家さんです。彼女はジャヒーのことを気遣ってくれる優しい人です。ジャヒーが「そうじゃない」と言っても、ついジャヒーを「ハイちゃん」と呼んでしまう傾向があります。 ジャヒーが変身できることを知ったとき、彼女はジャヒーがさらに可愛く思えた。彼女はジャヒーを恐れることなく、むしろ彼女の境遇に共感している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b133105-KIQgMplUFhoC.jpg', NULL, NULL, '茅野愛衣', NULL, 133105, 'SUPPORTING', 201) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023221', 'AN2028', 'おっさん魔法少女', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b246803-BQnftvGAcS5K.png', NULL, NULL, '堀秀行', NULL, 246803, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023222', 'AN2028', 'ドゥルジ', 'かつては闇の領域の住人だった。ジャヒーの忠実な使用人として、彼女は主人のためならどんなことでも喜んで行う。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b133104-cyO5IF7xaa2U.png', NULL, NULL, '花澤香菜', NULL, 133104, 'SUPPORTING', 220) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023223', 'AN2028', 'スー', '彼女は、神宮京子を魔法少女に変え、闇の世界からすべてのマナクリスタルを奪い取った、謎めいた光の存在である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258831-glPHV3sWWefb.png', NULL, NULL, '鬼頭明里', NULL, 258831, 'SUPPORTING', 50) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023224', 'AN2028', '心', 'ジャヒーと同じ町に住む若い少女。ジャヒーと出会った際、彼女は「闇の領域」を復活させるためにマナクリスタルを探す手助けをすることに同意した。彼女とジャヒーはすぐに親友になった。ジャヒーは、自分を理解してくれる数少ない人物の一人として彼女を頼りにしている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n133106-o4MDUjB3x7Xa.jpg', NULL, NULL, '小倉唯', NULL, 133106, 'SUPPORTING', 54) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023225', 'AN2028', 'サルワ', 'かつてはダークレルムの精鋭だった。人間界へと送り込まれ、そこで今もジャヒーを倒そうと奮闘している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b133107-fEBCGVHlOcGg.png', NULL, NULL, '小松未可子', NULL, 133107, 'SUPPORTING', 154) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023226', 'AN2028', '神宮きょうこ', 'ジャヒーの故郷の惑星を破壊した者。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b133102-mU3qfdTnRIff.jpg', NULL, NULL, '上坂すみれ', NULL, 133102, 'SUPPORTING', 119) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023227', 'AN2028', 'おじさん', '店長と親の叔父。海辺で焼きそば屋を営んでいる。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b254315-1fpIdBm6QzwS.png', NULL, NULL, '佐々木義人', NULL, 254315, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
