INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023311', 'AN2032', '北島浩二', '能力：地面に触れている間、触れたあらゆる能力の効果を無効化する。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b247494-YewB12Huwqbo.jpg', NULL, NULL, '隈本吉成', NULL, 247494, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
