INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023313', 'AN2032', '香椎 鈴', '能力：自身の体液から拷問器具を作り出すこと。 香椎鈴は『出会って5秒でバトル』シリーズの登場人物である。以前はOLだった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b208058-3fR8OoPrMhsx.png', NULL, NULL, '行成とあ', NULL, 208058, 'SUPPORTING', 108) ON CONFLICT DO NOTHING;
