INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023357', 'AN2035', '米倉マリナ', 'マリーナは、まるで太陽のような元気いっぱいの女の子です！ベネズエラにルーツがあり、時々スペイン語を話します。誰とでも気兼ねなく話せる性格で、海の生き物たちと過ごす時間をとても楽しんでいます。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b249344-6s9jJ9d52w8T.png', NULL, NULL, '東山奈央', NULL, 249344, 'SUPPORTING', 21) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023358', 'AN2035', '三浦響子', 'ククルスの最初のプランを却下したものの、2つ目のプランに心を奪われてしまうウェディングプランナー。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258189-mhG89a0YAgAc.jpg', NULL, NULL, '中原麻衣', NULL, 258189, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023359', 'AN2035', '照屋月美', '月見はククルの同級生で、小学校の頃から親友だ。彼女は、母親が経営するレストラン「カメ」を手伝う、優しい女の子だ。友達がよく店に集まってくるため、彼女のあだ名は「うどんちゃん」だ。 気さくで穏やかな性格だが、周囲のこともよく気遣うため、誰からも愛されている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b217015-ZYuTIy9TIN9P.png', NULL, NULL, '和氣あず未', NULL, 217015, 'SUPPORTING', 56) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023360', 'AN2035', '照屋さつき', '月見の母親。占い師。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b243232-byk9jweFmzDB.jpg', NULL, NULL, '儀武ゆう子', NULL, 243232, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023361', 'AN2035', '諏訪哲司', 'ティンガルラ水族館の共同館長。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b250131-1dq8CINgXciL.jpg', NULL, NULL, '日野聡', NULL, 250131, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023362', 'AN2035', '城居 ルカ', '「ヨナ・プロ」に所属するアイドルで、宮沢フカが脱退する前は彼女と仲が良かった。彼女は常にフカを尊敬すべき先輩として慕っており、フカのためにアイドル活動に一生懸命取り組む原動力にもしていた。出典：MAL', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b306301-XAW37hunu2mF.png', NULL, NULL, '菊池紗矢香', NULL, 306301, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023363', 'AN2035', '久高夏凛', 'カリンは、地元の観光協会で働く公務員です。水族館の手伝いもする、頼りになるお姉さん的存在です。ククルたちにとっては「年上の友人」のような存在です。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b217016-eUrt1ZD0TYfs.png', NULL, NULL, 'Lynn', NULL, 217016, 'SUPPORTING', 34) ON CONFLICT DO NOTHING;
