INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023411', 'AN2037', 'キャロット', 'キャロットは、『ピーチボーイ・リバーサイド』シリーズの登場人物の一人です。かつて「メキ」として知られていたハイ・オニで、力を失った後、サリーの旅に同行することになります。彼女は東の国出身のオニです。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b208338-EvPrDHPOEj6G.jpg', NULL, NULL, '戸田めぐみ', NULL, 208338, 'SUPPORTING', 120) ON CONFLICT DO NOTHING;
