INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023479', 'AN2040', '川窪ちぬ', '川窪ちぬは、メディアでも取り上げられる有名な水球選手だ。彼女は清水みなとの過去について知っている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b210792-eLaYhd1VeGMM.png', NULL, NULL, 'Lynn', 165, 210792, 'SUPPORTING', 69) ON CONFLICT DO NOTHING;
